// MONTAR EXPORT — junta Leads + Comerciais + Historico num formato pronto a
// converter para CSV do lado do Terminal (um comercial por id, um lead por linha).
const pega = nome => { try { return $(nome).all().map(i => i.json); } catch (e) { return []; } };
const F = r => r.fields || r;
const id = r => r.id || F(r).id || null;
const um = v => Array.isArray(v) ? (v[0] || null) : (v || null);
const txt = (f, ...ks) => { for (const k of ks) if (f[k] !== undefined && f[k] !== null && f[k] !== '') return f[k]; return null; };

const comerciaisPorId = {};
for (const r of pega('Comerciais')) {
  const f = F(r);
  comerciaisPorId[id(r)] = txt(f, 'Nome', 'nome') || '';
}

const leadsPorId = {};
const leads = pega('Leads').map(r => {
  const f = F(r);
  const lid = id(r);
  const comercialId = um(f.Comercial || f.Comerciais || f.comercial);
  const row = {
    id: lid,
    nome: txt(f, 'Nome', 'nome') || '',
    telefone: txt(f, 'Telefone', 'telefone') || '',
    email: txt(f, 'Email', 'email') || '',
    comercial: comerciaisPorId[comercialId] || '',
    estagio: txt(f, 'estagio', 'Estagio', 'Estágio') || '',
    status: txt(f, 'Status', 'status') || '',
    tipo: txt(f, 'tipo', 'Tipo') || '',
    origem_lead: txt(f, 'origem_lead', 'Origem') || '',
    valor: f.Valor ?? f.valor ?? '',
    banco_origem: txt(f, 'banco_origem') || '',
    motivo_saida: txt(f, 'motivo_saida') || '',
    ultima_nota: txt(f, 'ultima_nota', 'Ultima_nota') || '',
  };
  leadsPorId[lid] = row;
  return row;
}).filter(l => l.nome);

const historico = pega('Historico').map(r => {
  const f = F(r);
  const leadId = um(f.Lead || f.Leads);
  const lead = leadsPorId[leadId] || {};
  return {
    id: id(r),
    lead_nome: lead.nome || '',
    lead_telefone: lead.telefone || '',
    data: txt(f, 'Data', 'data') || '',
    tipo_registo: txt(f, 'tipo_registo') || '',
    desfecho: txt(f, 'desfecho') || '',
    nota: txt(f, 'nota', 'Nota') || '',
  };
}).filter(h => h.nota || h.lead_nome);

return [{ json: { ok: true, gerado_em: new Date().toISOString(), leads, historico } }];

// PREP IMPORT — normaliza o corpo do pedido.
const body = $input.first().json.body || $input.first().json || {};
const comercial_id = (body.comercial_id || '').trim();
const leads = Array.isArray(body.leads) ? body.leads : [];
const historico = Array.isArray(body.historico) ? body.historico : [];
const dry_run = body.dry_run !== false;

if (!comercial_id) throw new Error('comercial_id em falta.');
if (!leads.length && !historico.length) throw new Error('Nada para importar (leads e historico vazios).');

return [{ json: { comercial_id, leads, historico, dry_run } }];

// PLANEAR — decide o que fazer a cada linha, sem escrever nada ainda.
// Regras de segurança (CLAUDE.md: nunca apagar; decisões destrutivas ficam do lado do César):
//  - Lead existente (por telefone): só entram no upsert os campos que estejam VAZIOS no Airtable.
//    O telefone enviado ao upsert é sempre o valor JÁ existente, para o casamento por
//    matchingColumns bater certo com a mesma lógica de normalização usada aqui.
//  - Histórico: só é aceite quando há uma lead (existente ou a criar nesta importação) com
//    o mesmo telefone — nunca se inventa uma lead nova só para pendurar histórico.
const prep = $('Prep Import').first().json;
const { comercial_id, leads: linhasLeads, historico: linhasHist, dry_run } = prep;

const normTel = (t) => String(t || '').replace(/\D/g, '').slice(-9);
const limpo = (v) => (v === undefined || v === null) ? '' : String(v).trim();

let existentes = [];
try { existentes = $('Leads (existentes)').all().map(i => i.json); } catch (e) {}
const porTelefone = new Map();
for (const r of existentes) {
  const f = r.fields || r;
  const tel = normTel(f.Telefone || f.telefone);
  if (tel) porTelefone.set(tel, { id: r.id, fields: f });
}

const MAPA_LEAD = {
  nome: 'Nome', email: 'Email', estagio: 'estagio', status: 'Status', tipo: 'tipo',
  origem_lead: 'origem_lead', valor: 'Valor', banco_origem: 'banco_origem', ultima_nota: 'ultima_nota',
};

const avisos = [];
const leadsParaUpsert = [];
let leadsNovasCount = 0;
let leadsAtualizarCount = 0;
const telefonesConhecidos = new Set(porTelefone.keys()); // existentes + os que vamos criar/tocar agora

for (const linha of linhasLeads) {
  const nome = limpo(linha.nome);
  const tel = normTel(linha.telefone);
  if (!tel) { avisos.push(`Lead "${nome || '(sem nome)'}" sem telefone — ignorada (o import exige telefone para evitar duplicados).`); continue; }
  if (!nome) { avisos.push(`Lead com telefone ${tel} sem nome — ignorada.`); continue; }

  const existente = porTelefone.get(tel);
  const fields = {};
  if (existente) {
    // casamento pelo telefone JÁ guardado no Airtable — nunca o valor em bruto do CSV.
    fields.Telefone = existente.fields.Telefone || existente.fields.telefone;
    for (const [origem, destino] of Object.entries(MAPA_LEAD)) {
      if (origem === 'nome') continue; // nunca reescreve o nome de uma lead já existente
      const valorNovo = limpo(linha[origem]);
      const valorActual = existente.fields[destino];
      const vazio = valorActual === undefined || valorActual === null || valorActual === '';
      if (vazio && valorNovo) fields[destino] = destino === 'Valor' ? (Number(valorNovo) || valorNovo) : valorNovo;
    }
    if (!existente.fields.Comercial && !existente.fields.Comerciais) fields.Comercial = [comercial_id];
  } else {
    fields.Nome = nome;
    fields.Telefone = linha.telefone;
    fields.Comercial = [comercial_id];
    for (const [origem, destino] of Object.entries(MAPA_LEAD)) {
      if (origem === 'nome') continue;
      const v = limpo(linha[origem]);
      if (v) fields[destino] = destino === 'Valor' ? (Number(v) || v) : v;
    }
  }
  leadsParaUpsert.push({ _id: existente ? existente.id : null, fields });
  telefonesConhecidos.add(tel);
  if (existente) { if (Object.keys(fields).length > 1) leadsAtualizarCount++; }
  else leadsNovasCount++;
}

const historicoPendente = [];
for (const linha of linhasHist) {
  const tel = normTel(linha.lead_telefone);
  const nota = limpo(linha.nota);
  if (!nota) continue;
  if (!tel || !telefonesConhecidos.has(tel)) {
    avisos.push(`Histórico "${nota.slice(0, 40)}…" sem lead correspondente (telefone ${tel || '?'}) — ignorado.`);
    continue;
  }
  const dataDita = limpo(linha.data);
  historicoPendente.push({
    _tel: tel,
    fields: {
      Registo: 'Importado',
      tipo_registo: 'importado',
      // Data é campo calculado no Airtable (não aceita escrita) — a data original
      // do CRM de origem, quando existe, fica à cabeça da nota para não se perder.
      nota: (dataDita ? '['+dataDita+'] ' : '') + nota,
      ...(limpo(linha.desfecho) ? { desfecho: limpo(linha.desfecho) } : {}),
    },
  });
}

return [{ json: {
  comercial_id, dry_run,
  leadsParaUpsert, historicoPendente, avisos,
  leads_novas: leadsNovasCount,
  leads_a_atualizar: leadsAtualizarCount,
} }];

// EXPLODIR LEADS — transforma o plano num item por lead. "id" no topo (fora de
// "fields") é a convenção do n8n para o registo a actualizar; sem "id" é criação.
const rows = $('Planear').first().json.leadsParaUpsert || [];
return rows.map(r => ({ json: r._id ? { id: r._id, ...r.fields } : { ...r.fields } }));

// RESOLVER HISTORICO — depois de "Juntar Leads" (actualizadas + criadas), sabemos o
// id real de cada telefone tocado nesta importação. Resolve o Lead de cada linha de
// histórico já validada pelo Planear e devolve um item por linha, pronto para criar.
const normTel = (t) => String(t || '').replace(/\D/g, '').slice(-9);

const porTelefone = new Map();
try {
  for (const i of $('Leads (existentes)').all()) {
    const f = i.json.fields || i.json;
    const tel = normTel(f.Telefone || f.telefone);
    if (tel) porTelefone.set(tel, i.json.id);
  }
} catch (e) {}
try {
  for (const i of $('Juntar Leads').all()) {
    const f = i.json.fields || i.json;
    const tel = normTel(f.Telefone || f.telefone);
    if (tel && i.json.id) porTelefone.set(tel, i.json.id);
  }
} catch (e) {}

const pendentes = $('Planear').first().json.historicoPendente || [];
const out = [];
for (const linha of pendentes) {
  const leadId = porTelefone.get(linha._tel);
  if (!leadId) continue; // já foi avisado no Planear se realmente não existe; aqui só protege contra falha na escrita das leads
  out.push({ json: { ...linha.fields, Lead: [leadId] } });
}
return out;

// MONTAR RESUMO — chega aqui a partir do ramo dry-run (nada escrito) ou do fim do
// ramo real (depois de "Criar Historico"). Os números são sempre os do plano do
// Planear (que decide create-vs-update de forma determinística); quando o ramo real
// correu, confere que o upsert de facto tocou o número de leads esperado.
const plano = $('Planear').first().json;
const dry_run = plano.dry_run;
const avisos = [...plano.avisos];

if (!dry_run) {
  let leadsTocadas = -1;
  try { leadsTocadas = $('Juntar Leads').all().length; } catch (e) {}
  const esperado = plano.leadsParaUpsert.length;
  if (leadsTocadas !== esperado) avisos.push(`Esperava tocar ${esperado} leads, o Airtable confirmou ${leadsTocadas}.`);
}

let historicoCriado = plano.historicoPendente.length;
if (!dry_run) {
  try { historicoCriado = $('Criar Historico').all().length; } catch (e) { historicoCriado = 0; }
}

return [{ json: {
  ok: true,
  dry_run,
  leads_criadas: plano.leads_novas,
  leads_atualizadas: plano.leads_a_atualizar,
  historico_criado: historicoCriado,
  avisos,
} }];
